import{_ as o,o as e,c,a5 as s}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"点击穿透","description":"点击浮层关闭按钮时，也点击了页面上对应位置的元素（正常是不应该点击到页面上的对应的元素的） 原因 触屏设备为了区分用户双击缩放，对 click 做了 300ms 延迟触发，其在移动端的操作流程为 1. 手指触碰到屏幕时，触发 touchstart , 弹窗隐藏 2. 手指按上时。","frontmatter":{"title":"点击穿透","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"点击浮层关闭按钮时，也点击了页面上对应位置的元素（正常是不应该点击到页面上的对应的元素的） 原因 触屏设备为了区分用户双击缩放，对 click 做了 300ms 延迟触发，其在移动端的操作流程为 1. 手指触碰到屏幕时，触发 touchstart , 弹窗隐藏 2. 手指按上时。","sidebarWeight":87,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/事件/点击穿透.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/点击穿透.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/点击穿透.md"}'),l={name:"posts/JavaScript系统教程/04-浏览器与 Web API/点击穿透.md"};function a(i,t,n,r,g,u){return e(),c("div",null,[...t[0]||(t[0]=[s('<div><h1 id="点击穿透" tabindex="-1">点击穿透 <a class="header-anchor" href="#点击穿透" aria-label="Permalink to &quot;点击穿透&quot;">​</a></h1><blockquote><p>本节目标：理解“点击穿透”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 点击浮层关闭按钮时，也点击了页面上对应位置的元素（正常是不应该点击到页面上的对应的元素的） <strong>原因</strong> 触屏设备为了区分用户双击缩放，对 click 做了 300ms 延迟触发，其在移动端的操作流程为</p></blockquote><ol><li>手指触碰到屏幕时，触发 touchstart , 弹窗隐藏</li><li>手指按上时，可能会有短暂的停留和轻微的移动，触发 touchmove</li><li>手指离开屏幕时，触发 touchend</li><li>等待 300ms 后，看用户在此时间内是否再次触摸屏幕，如果没有</li><li><strong>300ms 后，此时弹窗已消失，浏览器在用户手指离开的位置触发 click 事件，所以点到了页面上的元素</strong></li></ol><p><strong>解决方案</strong> ❌方案1，增加 &lt;meta name=&quot;viewport&quot; content=&quot;device-width&quot;&gt; 虽然解决了 300ms 延迟，但是依然存在穿透现象，在 touchstart 里绑定了关闭弹窗，而 click 事件是在 touchend 事件之后（touchstart --&gt; touchend --&gt; click） 此时弹窗已消失，浏览器自动触发 click 事件，依然点到了页面上的相应位置。 测试</p><p>方案2 关闭弹窗时绑定的事件由 ontouchstart 变为 click ，因为（touchstart --&gt; touchend --&gt; click）手指离开时，会创建 click 时，就会有响应（touchstart --&gt; touchend 事件虽创建了，但是没绑定，所以也没有响应），弹窗隐藏，这个 click 事件响应到了弹窗上的关闭按钮， &lt;script&gt; const $ = s =&gt; document.querySelector(s) const log = str =&gt; $(&#39;.log&#39;).innerText = str let i = 1 $(&#39;.close&#39;).onclick = (e) =&gt; { //ontouchstart 改为 onclick $(&#39;.mask&#39;).style.display = &#39;none&#39; log(&#39;touched&#39; + (++i)) } $(&#39;.bg&#39;).onclick = () =&gt; { log(&#39;点击了背景&#39;) } &lt;/script&gt; 事件往上冒泡，但不会到 &#39;bg&#39; 上（是同级），会到 body 上，所以不会有穿透现象了 &lt;span class=&quot;bg&quot;&gt;背景&lt;/span&gt; &lt;p class=&quot;log&quot;&gt;0&lt;/p&gt; &lt;div class=&quot;mask&quot;&gt; &lt;span class=&quot;close&quot;&gt;X&lt;/span&gt; &lt;/div&gt; 测试</p><p>方案3 弹窗关闭的时间延长，比如让弹窗 300ms 以上渐变消失，此时 click 创建，点到这个位置时，点的还是弹窗，因为弹窗还没有消失，click 到了弹窗上，弹窗上没有绑定的事件，什么也不做，所以 click 到不了页面上对应的位置 &lt;style&gt; .fade { animation: fade .3s; animation-fill-mode: forwards; } .hide { display: none; } @keyframes fade { 0% { opacity: 100%; } 100% { opacity: 0; } } &lt;/style&gt; &lt;script&gt; const $ = s =&gt; document.querySelector(s) const log = str =&gt; $(&#39;.log&#39;).innerText = str let i = 1 $(&#39;.close&#39;).ontouchstart = (e) =&gt; { log(&#39;touched&#39; + (++i)) } $(&#39;.close&#39;).ontouchend = e =&gt; { $(&#39;.mask&#39;).classList.add(&#39;fade&#39;) //增加渐变动画 setTimeout(() =&gt; $(&#39;.mask&#39;).classList.add(&#39;hide&#39;), 300) } $(&#39;.bg&#39;).onclick = () =&gt; { log(&#39;点击了背景&#39;) } &lt;/script&gt; 测试</p><p>方案4 在 ontouchstart 里阻止默认事件，会阻止 默认 click 事件的创建，自然也不会响应到页面上的元素 &lt;script&gt; const $ = s =&gt; document.querySelector(s) const log = str =&gt; $(&#39;.log&#39;).innerText = str let i = 1 $(&#39;.close&#39;).ontouchstart = (e) =&gt; { e.preventDefault() //阻止默认事件 $(&#39;.mask&#39;).style.display = &#39;none&#39; log(&#39;touched&#39; + (++i)) } $(&#39;.bg&#39;).onclick = () =&gt; { log(&#39;点击了背景&#39;) } &lt;/script&gt; 测试</p><p>发布于 2019-09-02 &gt; 来自 &lt;<a href="https://zhuanlan.zhihu.com/p/80784312" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/80784312</a>&gt;</p></div>',1)])])}const h=o(l,[["render",a]]);export{d as __pageData,h as default};
